/**
 * @summary Get an AI-generated period summary for a growth plan
 */
export const getGetGrowthPlansIdSummaryUrl = (
  id: number,
  params?: GetGrowthPlansIdSummaryParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/growth/plans/${id}/summary?${stringifiedParams}`
    : `/api/growth/plans/${id}/summary`;
};

