/**
 * @summary Compare multiple hypotheses by ID
 */
export const getCompareHypothesesUrl = (params: CompareHypothesesParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/hypotheses/compare?${stringifiedParams}`
    : `/api/hypotheses/compare`;
};

export const compareHypotheses = async (
  params: CompareHypothesesParams,
  options?: RequestInit,
): Promise<CompareHypotheses200> => {
  return customFetch<CompareHypotheses200>(getCompareHypothesesUrl(params), {
    ...options,
    method: "GET",
  });
};

